package com.cinenest;
import com.nimbusds.jose.util.JSONObjectUtils;import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.core.env.Environment;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.test.context.*;import static org.assertj.core.api.Assertions.*;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"cinenest.advertising.enabled=true","spring.datasource.hikari.maximum-pool-size=5","spring.datasource.hikari.minimum-idle=0"})
@ActiveProfiles("local-synthetic")
@org.springframework.test.annotation.DirtiesContext(classMode=org.springframework.test.annotation.DirtiesContext.ClassMode.AFTER_CLASS)
class AdvertisingIntegrationTest {
 @Autowired JdbcClient jdbc;@Autowired Environment env;
 @BeforeEach void isolateThrottle(){jdbc.sql("TRUNCATE cinenest_identity.manual_throttle").update();}
 @DynamicPropertySource static void config(DynamicPropertyRegistry r){CustomerProfileIntegrationTest.config(r);String url=System.getenv("CINENEST_DB_URL"),u=System.getenv("CINENEST_DB_USER"),p=System.getenv("CINENEST_DB_PASSWORD");if(url==null||!url.startsWith("jdbc:postgresql://127.0.0.1:")||!url.endsWith("/cinenest_test"))throw new IllegalStateException("Disposable test database required");String name="ads_suite_"+UUID.randomUUID().toString().replace("-","");try(var c=java.sql.DriverManager.getConnection(url,u,p);var s=c.createStatement()){s.execute("CREATE DATABASE "+name);}catch(java.sql.SQLException e){throw new IllegalStateException("Isolated advertising database unavailable",e);}String target=url.substring(0,url.lastIndexOf('/')+1)+name;r.add("spring.datasource.url",()->target);}
 CustomerProfileIntegrationTest.Browser browser(){var fixture=new CustomerProfileIntegrationTest();fixture.jdbc=jdbc;fixture.env=env;return fixture.new Browser();}
 UUID venue(){UUID v=UUID.randomUUID();jdbc.sql("INSERT INTO cinenest_rooms.venue(venue_id,code,display_name,timezone,cleaning_buffer_minutes,enabled) VALUES(:v,:c,'Synthetic advertising venue','Asia/Colombo',30,true)").param("v",v).param("c","AD_"+v.toString().replace("-","").toUpperCase(java.util.Locale.ROOT)).update();jdbc.sql("INSERT INTO cinenest_rooms.venue_operating_window VALUES(:v,1,600,1320)").param("v",v).update();return v;}
 void grant(UUID a,UUID v,String...actions){jdbc.sql("INSERT INTO cinenest_identity.account_scope VALUES(:a,:v) ON CONFLICT DO NOTHING").param("a",a).param("v",v).update();for(String action:actions)jdbc.sql("INSERT INTO cinenest_identity.access_grant(grant_id,account_id,permission,scope_kind,venue_id,state,valid_from,valid_until) VALUES(:id,:a,:p,'VENUE',:v,'ACTIVE',clock_timestamp()-interval '1 minute',clock_timestamp()+interval '1 hour')").param("id",UUID.randomUUID()).param("a",a).param("p","content.banner."+action).param("v",v).update();}
 Map<String,Object> content(String title){return new LinkedHashMap<>(Map.of("title",title,"description","Synthetic non-financial banner","altText","Illustrative private cinema","assetId","violet","assetVersion",1,"startsAt","2026-01-01T00:00:00Z","endsAt","2030-01-01T00:00:00Z","displayOrder",10,"linkTarget","ROOMS"));}
 String root(UUID v){return "/api/admin/venues/"+v+"/banners";}
 Map<String,Object> json(String s)throws Exception{return JSONObjectUtils.parse(s);}
 Map<String,Object> create(CustomerProfileIntegrationTest.Browser b,UUID v)throws Exception{var r=b.call("POST",root(v),JSONObjectUtils.toJSONString(Map.of("commandId",UUID.randomUUID().toString(),"content",content("Synthetic banner"))),true);assertThat(r.statusCode()).as(r.body()).isEqualTo(200);return json(r.body());}
 Map<String,Object> detail(CustomerProfileIntegrationTest.Browser b,UUID v,Object id)throws Exception{var r=b.call("GET",root(v)+"/"+id,null,false);assertThat(r.statusCode()).as(r.body()).isEqualTo(200);return json(r.body());}
 String publication(Map<String,Object> d){return JSONObjectUtils.toJSONString(Map.of("commandId",UUID.randomUUID().toString(),"expectedRevision",d.get("resourceRevision"),"contentRevision",d.get("contentRevision"),"reviewHash",d.get("reviewHash")));}
 @Test void draftIndependentPublishingImmutableSnapshotAndUnpublish()throws Exception{var a=browser();UUID author=a.login(),v=venue();grant(author,v,"read","edit","publish");var p=browser();UUID publisher=p.login();grant(publisher,v,"read","publish");Object id=create(a,v).get("bannerId");var d=detail(a,v,id);assertThat(a.call("GET","/api/catalog/banners?venueId="+v,null,false).body()).isEqualTo("[]");assertThat(a.call("POST",root(v)+"/"+id+"/publications",publication(d),true).statusCode()).isEqualTo(403);assertThat(p.call("POST",root(v)+"/"+id+"/publications",publication(d),true).statusCode()).isEqualTo(200);assertThat(a.call("GET","/api/catalog/banners?venueId="+v,null,false).body()).contains("Synthetic banner").doesNotContain("reviewHash","authorId","resourceRevision");assertThat(a.call("PUT",root(v)+"/"+id,JSONObjectUtils.toJSONString(Map.of("commandId",UUID.randomUUID().toString(),"expectedRevision",2,"content",content("Private next draft"))),true).statusCode()).isEqualTo(200);assertThat(a.call("GET","/api/catalog/banners?venueId="+v,null,false).body()).doesNotContain("Private next draft");assertThat(p.call("GET",root(v)+"/"+id+"/revisions",null,false).body()).contains("Private next draft","Synthetic banner");assertThat(p.call("POST",root(v)+"/"+id+"/unpublish",JSONObjectUtils.toJSONString(Map.of("commandId",UUID.randomUUID().toString(),"expectedRevision",3)),true).statusCode()).isEqualTo(200);assertThat(a.call("GET","/api/catalog/banners?venueId="+v,null,false).body()).isEqualTo("[]");}
 @Test void duplicateCommandsConcurrencyAndChangedPayload()throws Exception{var a=browser();UUID author=a.login(),v=venue();grant(author,v,"read","edit");String body=JSONObjectUtils.toJSONString(Map.of("commandId",UUID.randomUUID().toString(),"content",content("Replay")));var first=a.call("POST",root(v),body,true);assertThat(first.statusCode()).isEqualTo(200);assertThat(a.call("POST",root(v),body,true).body()).contains("\"replayed\":true");assertThat(a.call("POST",root(v),body.replace("Replay","Altered"),true).statusCode()).isEqualTo(409);Object id=json(first.body()).get("bannerId");var executor=Executors.newFixedThreadPool(2);try{var tasks=new ArrayList<Future<Integer>>();for(int i=0;i<2;i++)tasks.add(executor.submit(()->a.call("PUT",root(v)+"/"+id,JSONObjectUtils.toJSONString(Map.of("commandId",UUID.randomUUID().toString(),"expectedRevision",1,"content",content("Concurrent"))),true).statusCode()));assertThat(List.of(tasks.get(0).get(),tasks.get(1).get())).containsExactlyInAnyOrder(200,409);}finally{executor.shutdownNow();}assertThat(jdbc.sql("SELECT count(*) FROM cinenest_rooms.banner WHERE venue_id=:v").param("v",v).query(Integer.class).single()).isEqualTo(1);}
 @Test void authorityCsrfAssetAndIntegrityNegatives()throws Exception{var a=browser();UUID author=a.login(),v=venue();grant(author,v,"read","edit");assertThat(a.call("POST",root(v),"{}",false).statusCode()).isEqualTo(403);assertThat(a.call("GET",root(venue()),null,false).statusCode()).isEqualTo(403);assertThat(browser().call("GET",root(v),null,false).statusCode()).isEqualTo(401);var bad=content("Bad");bad.put("assetId","../../receipt");assertThat(a.call("POST",root(v),JSONObjectUtils.toJSONString(Map.of("commandId",UUID.randomUUID().toString(),"content",bad)),true).statusCode()).isEqualTo(400);Object id=create(a,v).get("bannerId");assertThatThrownBy(()->jdbc.sql("UPDATE cinenest_rooms.banner_revision SET title='tamper' WHERE banner_id=:id").param("id",UUID.fromString(id.toString())).update()).isInstanceOf(Exception.class);for(String table:List.of("banner_revision","banner_audit","banner_command","banner"))assertThatThrownBy(()->jdbc.sql("TRUNCATE cinenest_rooms."+table+" CASCADE").update()).isInstanceOf(Exception.class);assertThatThrownBy(()->jdbc.sql("UPDATE cinenest_rooms.banner SET resource_revision=resource_revision+1 WHERE banner_id=:id").param("id",UUID.fromString(id.toString())).update()).isInstanceOf(Exception.class);jdbc.sql("UPDATE cinenest_identity.access_grant SET state='REVOKED',revision=revision+1 WHERE account_id=:a AND venue_id=:v").param("a",author).param("v",v).update();assertThat(a.call("GET",root(v),null,false).statusCode()).isEqualTo(403);}
 @Test void auditUnavailableRollsBack()throws Exception{var a=browser();UUID author=a.login(),v=venue();grant(author,v,"read","edit");jdbc.sql("CREATE FUNCTION cinenest_rooms.banner_test_fail() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'synthetic audit unavailable'; END $$").update();jdbc.sql("CREATE TRIGGER banner_test_fail BEFORE INSERT ON cinenest_rooms.banner_audit FOR EACH ROW EXECUTE FUNCTION cinenest_rooms.banner_test_fail()").update();try{var r=a.call("POST",root(v),JSONObjectUtils.toJSONString(Map.of("commandId",UUID.randomUUID().toString(),"content",content("No commit"))),true);assertThat(r.statusCode()).isEqualTo(503);assertThat(jdbc.sql("SELECT count(*) FROM cinenest_rooms.banner WHERE venue_id=:v").param("v",v).query(Integer.class).single()).isZero();assertThat(a.call("GET",root(v),null,false).statusCode()).isEqualTo(503);}finally{jdbc.sql("DROP TRIGGER banner_test_fail ON cinenest_rooms.banner_audit").update();jdbc.sql("DROP FUNCTION cinenest_rooms.banner_test_fail()").update();}}
 @Test void cleanAndUpgradePath()throws Exception{String db="ads_upgrade_"+UUID.randomUUID().toString().replace("-","");jdbc.sql("CREATE DATABASE "+db).update();String url=env.getRequiredProperty("spring.datasource.url");String target=url.substring(0,url.lastIndexOf('/')+1)+db,u=env.getRequiredProperty("spring.datasource.username"),p=env.getRequiredProperty("spring.datasource.password");var old=org.flywaydb.core.Flyway.configure().dataSource(target,u,p).target("29").load();old.migrate();UUID v=UUID.randomUUID();try(var c=java.sql.DriverManager.getConnection(target,u,p);var s=c.createStatement()){s.execute("INSERT INTO cinenest_rooms.venue(venue_id,code,display_name,timezone) VALUES('"+v+"','PRESERVED','Preserved','UTC')");}var latest=org.flywaydb.core.Flyway.configure().dataSource(target,u,p).target("30").load();assertThat(latest.migrate().migrationsExecuted).isEqualTo(1);latest.validate();assertThat(latest.info().current().getVersion().toString()).isEqualTo("30");try(var c=java.sql.DriverManager.getConnection(target,u,p);var s=c.createStatement();var r=s.executeQuery("SELECT count(*) FROM cinenest_rooms.venue WHERE venue_id='"+v+"'")){assertThat(r.next()).isTrue();assertThat(r.getInt(1)).isEqualTo(1);}}

 @Test void serverScheduleAndOrdering()throws Exception{var a=browser();UUID author=a.login(),v=venue();grant(author,v,"read","edit");var p=browser();UUID publisher=p.login();grant(publisher,v,"read","publish");for(int order:List.of(20,1)){var c=content("Order "+order);c.put("displayOrder",order);var result=a.call("POST",root(v),JSONObjectUtils.toJSONString(Map.of("commandId",UUID.randomUUID().toString(),"content",c)),true);Object id=json(result.body()).get("bannerId");assertThat(p.call("POST",root(v)+"/"+id+"/publications",publication(detail(p,v,id)),true).statusCode()).isEqualTo(200);}String body=a.call("GET","/api/catalog/banners?venueId="+v,null,false).body();assertThat(body.indexOf("Order 1")).isLessThan(body.indexOf("Order 20"));UUID futureVenue=venue();grant(author,futureVenue,"read","edit");grant(publisher,futureVenue,"read","publish");var c=content("Future");c.put("startsAt","2035-01-01T00:00:00Z");c.put("endsAt","2036-01-01T00:00:00Z");var result=a.call("POST",root(futureVenue),JSONObjectUtils.toJSONString(Map.of("commandId",UUID.randomUUID().toString(),"content",c)),true);Object id=json(result.body()).get("bannerId");assertThat(p.call("POST",root(futureVenue)+"/"+id+"/publications",publication(detail(p,futureVenue,id)),true).statusCode()).isEqualTo(200);assertThat(a.call("GET","/api/catalog/banners?venueId="+futureVenue,null,false).body()).isEqualTo("[]");assertThat(detail(p,futureVenue,id).get("status")).isEqualTo("SCHEDULED");var expired=content("Expired");expired.put("startsAt","2019-01-01T00:00:00Z");expired.put("endsAt","2020-01-01T00:00:00Z");assertThat(a.call("PUT",root(futureVenue)+"/"+id,JSONObjectUtils.toJSONString(Map.of("commandId",UUID.randomUUID().toString(),"expectedRevision",2,"content",expired)),true).statusCode()).isEqualTo(200);assertThat(p.call("POST",root(futureVenue)+"/"+id+"/publications",publication(detail(p,futureVenue,id)),true).statusCode()).isEqualTo(200);assertThat(detail(p,futureVenue,id).get("status")).isEqualTo("EXPIRED");assertThat(a.call("GET","/api/catalog/banners?venueId="+futureVenue,null,false).body()).isEqualTo("[]");jdbc.sql("UPDATE cinenest_rooms.venue SET enabled=false,version=version+1 WHERE venue_id=:v").param("v",v).update();assertThat(a.call("GET","/api/catalog/banners?venueId="+v,null,false).body()).isEqualTo("[]");}
 @Test @org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable(named="CINENEST_ADVERTISING_E2E",matches="true")
 void realStackBrowser()throws Exception{var a=browser();UUID author=a.login(),v=venue();grant(author,v,"read","edit","publish");var p=browser();UUID publisher=p.login();grant(publisher,v,"read","publish");Map<String,Long> invariantCounts=new LinkedHashMap<>();for(String table:List.of("cinenest_identity.account","cinenest_identity.external_identity","cinenest_identity.access_grant"))invariantCounts.put(table,jdbc.sql("SELECT count(*) FROM "+table).query(Long.class).single());var run=java.nio.file.Files.createTempDirectory("cinenest-ads-e2e-");String emailA=jdbc.sql("SELECT email FROM cinenest_identity.manual_customer WHERE account_id=:a").param("a",author).query(String.class).single(),emailP=jdbc.sql("SELECT email FROM cinenest_identity.manual_customer WHERE account_id=:a").param("a",publisher).query(String.class).single();java.nio.file.Files.writeString(run.resolve("config.json"),JSONObjectUtils.toJSONString(Map.of("backend",aBase(),"author",emailA,"publisher",emailP,"password",CustomerProfileIntegrationTest.PASSWORD,"venue",v.toString())));var process=new ProcessBuilder("node",java.nio.file.Path.of("../frontend/tests/banners-e2e.mjs").toAbsolutePath().toString(),run.toString()).redirectErrorStream(true).redirectOutput(run.resolve("browser.log").toFile()).start();try{assertThat(process.waitFor(4,TimeUnit.MINUTES)).isTrue();assertThat(process.exitValue()).as("Inspect private browser harness log "+run).isZero();assertThat(json(java.nio.file.Files.readString(run.resolve("results.json"))).get("status")).isEqualTo("PASS");for(var e:invariantCounts.entrySet())assertThat(jdbc.sql("SELECT count(*) FROM "+e.getKey()).query(Long.class).single()).isEqualTo(e.getValue());for(String table:List.of("cinenest_payments.bank_payment_request","cinenest_payments.incoming_payment_credit","cinenest_payments.payment_allocation","cinenest_booking.booking","cinenest_access.access_credential","cinenest_iot.device"))assertThat(jdbc.sql("SELECT count(*) FROM "+table).query(Integer.class).single()).isZero();}finally{if(process.isAlive()){process.destroy();process.waitFor(10,TimeUnit.SECONDS);}}}
 String aBase(){return "http://127.0.0.1:"+env.getRequiredProperty("local.server.port");}

 @Test void concurrentDuplicateCreateAndRevocationWait()throws Exception{var a=browser();UUID author=a.login(),v=venue();grant(author,v,"read","edit");String body=JSONObjectUtils.toJSONString(Map.of("commandId",UUID.randomUUID().toString(),"content",content("Concurrent command")));var executor=Executors.newFixedThreadPool(2);try{var one=executor.submit(()->a.call("POST",root(v),body,true));var two=executor.submit(()->a.call("POST",root(v),body,true));assertThat(one.get().statusCode()).isEqualTo(200);assertThat(two.get().statusCode()).isEqualTo(200);assertThat(jdbc.sql("SELECT count(*) FROM cinenest_rooms.banner WHERE venue_id=:v").param("v",v).query(Integer.class).single()).isEqualTo(1);assertThat(jdbc.sql("SELECT count(*) FROM cinenest_rooms.banner_command WHERE actor_id=:a").param("a",author).query(Integer.class).single()).isEqualTo(1);try(var connection=java.sql.DriverManager.getConnection(env.getRequiredProperty("spring.datasource.url"),env.getRequiredProperty("spring.datasource.username"),env.getRequiredProperty("spring.datasource.password"))){connection.setAutoCommit(false);try(var s=connection.prepareStatement("UPDATE cinenest_identity.access_grant SET state='REVOKED',revision=revision+1 WHERE account_id=? AND venue_id=?")){s.setObject(1,author);s.setObject(2,v);s.executeUpdate();}var ready=new CountDownLatch(1);var waiting=executor.submit(()->{ready.countDown();return a.call("GET",root(v),null,false).statusCode();});assertThat(ready.await(2,TimeUnit.SECONDS)).isTrue();assertThatThrownBy(()->waiting.get(150,TimeUnit.MILLISECONDS)).isInstanceOf(TimeoutException.class);connection.commit();assertThat(waiting.get(5,TimeUnit.SECONDS)).isEqualTo(403);}}finally{executor.shutdownNow();}}
}
